            'errors'  => ['mode' => ['月結制課程不支援此操作，請使用 renew-monthly 端點。']],
        ], 422);
    }

    $data = $request->validate([
        'sessions' => 'required|integer|min:1|max:500',
        'start_date' => 'required|date',
        'mode' => 'nullable|in:new_purchase',
    ]);

